/* One-to-one WebRTC video calling. Audio/video travel directly between the two browsers. */
const callPanel=document.querySelector('#callPanel'),localVideo=document.querySelector('#localVideo'),remoteVideo=document.querySelector('#remoteVideo'),callStatus=document.querySelector('#callStatus'),incomingCall=document.querySelector('#incomingCall');
let localStream=null,peerConnection=null,pendingCandidates=[],incomingInvite=null,callActive=false;
const rtcConfig={iceServers:[{urls:'stun:stun.l.google.com:19302'}]};
function setCallStatus(text){callStatus.textContent=text}
function showCall(){callPanel.hidden=false}
function stopMedia(){if(localStream){localStream.getTracks().forEach(track=>track.stop());localStream=null}localVideo.srcObject=null}
function closeCall(sendSignal=false){if(sendSignal&&roomId)socket.emit('call-ended',{});if(peerConnection){peerConnection.ontrack=null;peerConnection.close();peerConnection=null}pendingCandidates=[];remoteVideo.srcObject=null;callPanel.hidden=true;callActive=false;incomingInvite=null;if(incomingCall.open)incomingCall.close();stopMedia()}
async function getCamera(){if(localStream)return localStream;if(!navigator.mediaDevices?.getUserMedia)throw new Error('Camera access is not supported in this browser.');localStream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});localVideo.srcObject=localStream;return localStream}
function createPeer(){if(peerConnection)return peerConnection;peerConnection=new RTCPeerConnection(rtcConfig);localStream.getTracks().forEach(track=>peerConnection.addTrack(track,localStream));peerConnection.ontrack=event=>{remoteVideo.srcObject=event.streams[0];setCallStatus('Connected');callActive=true};peerConnection.onicecandidate=event=>{if(event.candidate)socket.emit('webrtc-ice',{candidate:event.candidate})};peerConnection.onconnectionstatechange=()=>{if(peerConnection?.connectionState==='failed'){notify('Video connection failed.');closeCall(false)}};return peerConnection}
async function startOffer(){let pc=createPeer();let offer=await pc.createOffer();await pc.setLocalDescription(offer);socket.emit('webrtc-offer',{offer:pc.localDescription});setCallStatus('Connecting…')}
async function startCall(){if(!roomId)return notify('Join a room before starting a call.');if(people.length<2)return notify('Invite someone to this room first.');if(people.length>2)return notify('Video calls support two people per room.');try{await getCamera();showCall();setCallStatus('Calling…');socket.emit('call-invite',{})}catch(error){stopMedia();notify(error.name==='NotAllowedError'?'Camera and microphone permission was denied.':'Could not start the camera.')}}
async function startCameraPreview(){if(callActive)return;try{await getCamera();showCall();setCallStatus('Camera preview');notify('Camera is on. Start a video call when you are ready.')}catch(error){stopMedia();notify(error.name==='NotAllowedError'?'Camera and microphone permission was denied.':'Could not start the camera.')}}
document.querySelector('#cameraButton').addEventListener('click',startCameraPreview);document.querySelector('#videoCallButton').addEventListener('click',startCall);document.querySelector('#endCall').addEventListener('click',()=>closeCall(true));
document.querySelector('#cameraToggle').addEventListener('click',event=>{let track=localStream?.getVideoTracks()[0];if(!track)return;track.enabled=!track.enabled;event.currentTarget.classList.toggle('off',!track.enabled);event.currentTarget.setAttribute('aria-label',track.enabled?'Turn camera off':'Turn camera on')});
document.querySelector('#muteToggle').addEventListener('click',event=>{let track=localStream?.getAudioTracks()[0];if(!track)return;track.enabled=!track.enabled;event.currentTarget.classList.toggle('off',!track.enabled);event.currentTarget.setAttribute('aria-label',track.enabled?'Mute microphone':'Unmute microphone')});
socket.on('call-invite',data=>{if(callActive||incomingCall.open){socket.emit('call-declined',{});return}incomingInvite=data;document.querySelector('#incomingCaller').textContent=`${data.name||'Someone'} is calling`;incomingCall.showModal()});
document.querySelector('#declineCall').addEventListener('click',()=>{socket.emit('call-declined',{});incomingInvite=null;incomingCall.close()});
document.querySelector('#acceptCall').addEventListener('click',async()=>{try{await getCamera();showCall();setCallStatus('Connecting…');incomingCall.close();socket.emit('call-accepted',{})}catch(error){socket.emit('call-declined',{});incomingCall.close();incomingInvite=null;stopMedia();notify(error.name==='NotAllowedError'?'Camera and microphone permission was denied.':'Could not start the camera.')}});
socket.on('call-accepted',async()=>{if(!localStream)return;try{await startOffer()}catch{notify('Could not connect the video call.');closeCall(true)}});
socket.on('call-declined',()=>{if(localStream&&!peerConnection){notify('The call was declined.');closeCall(false)}});
socket.on('webrtc-offer',async data=>{try{if(!localStream)await getCamera();showCall();let pc=createPeer();await pc.setRemoteDescription(data.offer);for(const candidate of pendingCandidates)await pc.addIceCandidate(candidate);pendingCandidates=[];let answer=await pc.createAnswer();await pc.setLocalDescription(answer);socket.emit('webrtc-answer',{answer:pc.localDescription});setCallStatus('Connecting…')}catch{notify('Could not answer the video call.');closeCall(true)}});
socket.on('webrtc-answer',async data=>{try{if(peerConnection)await peerConnection.setRemoteDescription(data.answer)}catch{notify('Could not connect the video call.');closeCall(true)}});
socket.on('webrtc-ice',async data=>{if(!data.candidate)return;try{if(peerConnection?.remoteDescription)await peerConnection.addIceCandidate(data.candidate);else pendingCandidates.push(data.candidate)}catch{}});
socket.on('call-ended',()=>{if(localStream||peerConnection||incomingCall.open){notify('The video call ended.');closeCall(false)}});
window.addEventListener('beforeunload',()=>closeCall(true));
